UPDATE dtb_order
SET customer_id = CASE WHEN JSON_VALUE(CAST(:order AS JSON), '$.customerId') REGEXP '^[0-9]+$' THEN CAST(JSON_VALUE(CAST(:order AS JSON), '$.customerId') AS UNSIGNED) ELSE NULL END,
    payment_id = NULLIF(CAST(JSON_VALUE(CAST(:order AS JSON), '$.paymentMethodId') AS SIGNED), 0), subtotal = CAST(JSON_VALUE(CAST(:order AS JSON), '$.subtotal') AS SIGNED), delivery_fee_total = CAST(JSON_VALUE(CAST(:order AS JSON), '$.deliveryFeeTotal') AS SIGNED), charge = CAST(JSON_VALUE(CAST(:order AS JSON), '$.charge') AS SIGNED), discount = CAST(JSON_VALUE(CAST(:order AS JSON), '$.discount') AS SIGNED), tax = CAST(JSON_VALUE(CAST(:order AS JSON), '$.tax') AS SIGNED), total = CAST(JSON_VALUE(CAST(:order AS JSON), '$.total') AS SIGNED), payment_total = CAST(JSON_VALUE(CAST(:order AS JSON), '$.paymentTotal') AS SIGNED), add_point = CAST(JSON_VALUE(CAST(:order AS JSON), '$.addPoint') AS SIGNED), use_point = CAST(JSON_VALUE(CAST(:order AS JSON), '$.usePoint') AS SIGNED), order_status_id = CAST(JSON_VALUE(CAST(:order AS JSON), '$.orderStatus') AS SIGNED), order_date = NULLIF(REPLACE(JSON_VALUE(CAST(:order AS JSON), '$.orderDate'), 'T', ' '), ''), payment_date = NULLIF(REPLACE(JSON_VALUE(CAST(:order AS JSON), '$.paymentDate'), 'T', ' '), ''), update_date = NOW()
WHERE order_no = JSON_VALUE(CAST(:order AS JSON), '$.orderNo')
